@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-jetbrains-mono);
  --font-mono: var(--font-jetbrains-mono);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
  --radius-4xl: calc(var(--radius) + 16px);
}

/* Dark-first: dark is the default (:root), light is the override */
:root {
  --radius: 0.5rem;
  --background: oklch(0.12 0 0);
  --foreground: oklch(0.9 0.02 85);
  --card: oklch(0.16 0 0);
  --card-foreground: oklch(0.9 0.02 85);
  --popover: oklch(0.16 0 0);
  --popover-foreground: oklch(0.9 0.02 85);
  --primary: oklch(0.75 0.18 55);
  --primary-foreground: oklch(0.12 0 0);
  --secondary: oklch(0.2 0 0);
  --secondary-foreground: oklch(0.85 0.01 85);
  --muted: oklch(0.2 0 0);
  --muted-foreground: oklch(0.55 0 0);
  --accent: oklch(0.75 0.18 55);
  --accent-foreground: oklch(0.12 0 0);
  --destructive: oklch(0.65 0.22 25);
  --border: oklch(1 0 0 / 8%);
  --input: oklch(1 0 0 / 12%);
  --ring: oklch(0.75 0.18 55);
  --chart-1: oklch(0.75 0.18 55);
  --chart-2: oklch(0.7 0.15 160);
  --chart-3: oklch(0.65 0.2 300);
  --chart-4: oklch(0.8 0.15 85);
  --chart-5: oklch(0.6 0.2 200);
  --sidebar: oklch(0.14 0 0);
  --sidebar-foreground: oklch(0.9 0.02 85);
  --sidebar-primary: oklch(0.75 0.18 55);
  --sidebar-primary-foreground: oklch(0.12 0 0);
  --sidebar-accent: oklch(0.2 0 0);
  --sidebar-accent-foreground: oklch(0.9 0.02 85);
  --sidebar-border: oklch(1 0 0 / 8%);
  --sidebar-ring: oklch(0.75 0.18 55);
}

.light {
  --background: oklch(0.985 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.65 0.2 50);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.96 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.96 0 0);
  --muted-foreground: oklch(0.45 0 0);
  --accent: oklch(0.65 0.2 50);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.9 0 0);
  --input: oklch(0.9 0 0);
  --ring: oklch(0.65 0.2 50);
  --chart-1: oklch(0.65 0.2 50);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(0.97 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.65 0.2 50);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.96 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.9 0 0);
  --sidebar-ring: oklch(0.65 0.2 50);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* --- custom animations --- */

@keyframes glow-pulse {
  0%,
  100% {
    text-shadow: 0 0 8px oklch(0.75 0.18 55 / 0.4);
  }
  50% {
    text-shadow:
      0 0 16px oklch(0.75 0.18 55 / 0.6),
      0 0 32px oklch(0.75 0.18 55 / 0.2);
  }
}

.glow-pulse {
  animation: glow-pulse 3s ease-in-out 1s infinite;
}

/* --- markdown prose for assistant messages --- */

.prose-msg {
  line-height: 1.6;
}

.prose-msg > *:first-child {
  margin-top: 0;
}

.prose-msg > *:last-child {
  margin-bottom: 0;
}

.prose-msg p {
  margin: 0.5em 0;
}

.prose-msg h1,
.prose-msg h2,
.prose-msg h3,
.prose-msg h4 {
  font-weight: 600;
  margin: 1em 0 0.5em;
}

.prose-msg h1 {
  font-size: 1.25em;
}

.prose-msg h2 {
  font-size: 1.125em;
}

.prose-msg h3 {
  font-size: 1em;
}

.prose-msg strong {
  font-weight: 700;
}

.prose-msg code {
  background: oklch(1 0 0 / 8%);
  border-radius: 0.25rem;
  padding: 0.15em 0.35em;
  font-size: 0.875em;
}

.prose-msg pre {
  background: oklch(0 0 0 / 40%);
  border-radius: 0.375rem;
  padding: 0.75em 1em;
  margin: 0.5em 0;
  overflow-x: auto;
}

.prose-msg pre code {
  background: none;
  padding: 0;
  font-size: 0.8125em;
  line-height: 1.5;
}

.prose-msg ul,
.prose-msg ol {
  margin: 0.5em 0;
  padding-left: 1.5em;
}

.prose-msg ul {
  list-style-type: disc;
}

.prose-msg ol {
  list-style-type: decimal;
}

.prose-msg li {
  margin: 0.2em 0;
}

.prose-msg li > ul,
.prose-msg li > ol {
  margin: 0.1em 0;
}

.prose-msg blockquote {
  border-left: 3px solid oklch(1 0 0 / 15%);
  padding-left: 0.75em;
  margin: 0.5em 0;
  color: var(--muted-foreground);
}

.prose-msg a {
  color: var(--primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.prose-msg a:hover {
  opacity: 0.8;
}

.prose-msg hr {
  border: none;
  border-top: 1px solid oklch(1 0 0 / 10%);
  margin: 0.75em 0;
}

.prose-msg table {
  border-collapse: collapse;
  margin: 0.5em 0;
  font-size: 0.875em;
  width: 100%;
}

.prose-msg th,
.prose-msg td {
  border: 1px solid oklch(1 0 0 / 12%);
  padding: 0.35em 0.6em;
  text-align: left;
}

.prose-msg th {
  font-weight: 600;
  background: oklch(1 0 0 / 5%);
}

.prose-msg img {
  max-width: 100%;
  border-radius: 0.375rem;
}

/* Light theme overrides for prose */
.light .prose-msg code {
  background: oklch(0 0 0 / 6%);
}

.light .prose-msg pre {
  background: oklch(0 0 0 / 5%);
}

.light .prose-msg blockquote {
  border-left-color: oklch(0 0 0 / 15%);
}

.light .prose-msg hr {
  border-top-color: oklch(0 0 0 / 10%);
}

.light .prose-msg th,
.light .prose-msg td {
  border-color: oklch(0 0 0 / 12%);
}

.light .prose-msg th {
  background: oklch(0 0 0 / 4%);
}

