"use client";

/**
 * Tool approval card shown when Claude requests permission to run a tool.
 *
 * Displays the tool name, optional description, and formatted input params
 * with Allow / Deny buttons. Once the user responds, buttons are replaced
 * with a status badge. Rendered in place of a regular {@link Message} when
 * the message carries a `controlRequest` payload.
 */

import { ShieldAlert, Check, X } from "lucide-react";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import type { ChatMessage } from "@/lib/types";
import { cn } from "@/lib/utils";

/** Format a tool name for display: strip namespace prefixes, convert to title. */
function formatToolName(name: string): string {
  // e.g. "Bash" stays "Bash", "mcp__something__tool" → "tool"
  const parts = name.split("__");
  return parts[parts.length - 1];
}

/** Render a single input value, truncating long strings. */
function InputValue({ value }: { value: unknown }) {
  if (value === null || value === undefined) {
    return <span className="text-muted-foreground italic">null</span>;
  }
  if (typeof value === "boolean") {
    return <span className="text-blue-400">{String(value)}</span>;
  }
  if (typeof value === "number") {
    return <span className="text-blue-400">{value}</span>;
  }
  if (typeof value === "string") {
    // For long strings (file contents, code, commands), show in a code block
    if (value.includes("\n") || value.length > 120) {
      return (
        <pre className="mt-1 max-h-60 overflow-auto rounded bg-black/30 p-2 text-xs leading-relaxed whitespace-pre-wrap break-all">
          {value}
        </pre>
      );
    }
    return (
      <code className="rounded bg-black/20 px-1.5 py-0.5 text-xs break-all">
        {value}
      </code>
    );
  }
  // Objects / arrays — JSON dump
  return (
    <pre className="mt-1 max-h-40 overflow-auto rounded bg-black/30 p-2 text-xs leading-relaxed">
      {JSON.stringify(value, null, 2)}
    </pre>
  );
}

export function ControlRequest({
  message,
  onRespond,
}: {
  message: ChatMessage;
  onRespond: (requestId: string, allow: boolean) => void;
}) {
  const cr = message.controlRequest;
  if (!cr) return null;

  const [respondedWith, setRespondedWith] = useState<
    "allowed" | "denied" | null
  >(null);

  const resolved = cr.resolved || respondedWith !== null;
  const displayName = formatToolName(cr.tool_name);
  const entries = Object.entries(cr.input);

  function handleRespond(allow: boolean) {
    setRespondedWith(allow ? "allowed" : "denied");
    onRespond(cr.id, allow);
  }

  return (
    <div
      className={cn(
        "w-full max-w-2xl rounded-lg border p-4",
        resolved
          ? "border-muted-foreground/15 bg-secondary/50"
          : "border-primary/30 bg-secondary"
      )}
    >
      {/* Header */}
      <div className="mb-3 flex items-center gap-2">
        <ShieldAlert
          className={cn(
            "h-4 w-4 shrink-0",
            resolved ? "text-muted-foreground" : "text-primary"
          )}
        />
        <span className="text-xs font-medium text-muted-foreground">
          Tool approval
        </span>
        <span className="text-sm font-semibold">{displayName}</span>
        {cr.tool_name !== displayName && (
          <span className="text-xs text-muted-foreground">
            ({cr.tool_name})
          </span>
        )}
      </div>

      {/* Description */}
      {cr.description && (
        <p className="mb-3 text-sm text-muted-foreground">{cr.description}</p>
      )}

      {/* Input parameters */}
      {entries.length > 0 && (
        <div className="mb-4 space-y-2">
          {entries.map(([key, value]) => (
            <div key={key}>
              <div className="text-xs font-medium text-muted-foreground">
                {key}
              </div>
              <div className="mt-0.5 text-sm">
                <InputValue value={value} />
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Actions / Status */}
      {!resolved ? (
        <div className="flex gap-2">
          <Button size="sm" onClick={() => handleRespond(true)}>
            <Check className="mr-1 h-3.5 w-3.5" />
            Allow
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => handleRespond(false)}
          >
            <X className="mr-1 h-3.5 w-3.5" />
            Deny
          </Button>
        </div>
      ) : (
        <div
          className={cn(
            "inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-medium",
            respondedWith === "denied"
              ? "bg-destructive/15 text-destructive"
              : "bg-primary/15 text-primary"
          )}
        >
          {respondedWith === "denied" ? (
            <>
              <X className="h-3 w-3" /> Denied
            </>
          ) : (
            <>
              <Check className="h-3 w-3" /> Allowed
            </>
          )}
        </div>
      )}
    </div>
  );
}

